#!/usr/bin/env python3
import sys, os, re, json, html as htmlmod
from dataclasses import dataclass, field
from typing import List, Optional, Any, Tuple

HELP = """Command-line XML and HTML beautifier and content extractor

Usage:
  xq [flags]

Flags:
  -a, --attr string      Extract an attribute value instead of node content for provided CSS query
  -c, --color            Force colorful output
      --compact          Compact JSON output (no indentation)
  -d, --depth int        Maximum nesting depth for JSON output (-1 for unlimited) (default -1)
  -e, --extract string   Extract a single node from XML
  -h, --help             Print this help message
  -m, --html             Use HTML formatter
  -i, --in-place         Format file in place
      --indent int       Use the given number of spaces for indentation (default 2)
  -j, --json             Output the result as JSON
      --no-color         Disable colorful output
  -n, --node             Return the node content instead of text
  -q, --query string     Extract the node(s) using CSS selector
      --tab              Use tabs for indentation
  -v, --version          Print version information
  -x, --xpath string     Extract the node(s) from XML
"""

VOID_HTML = set('area base br col embed hr img input link meta param source track wbr command keygen menuitem'.split())

@dataclass
class Text:
    text: str
    cdata: bool=False

@dataclass
class Comment:
    text: str

@dataclass
class Special:
    kind: str  # decl, doctype, pi
    text: str

@dataclass
class Node:
    tag: str
    attrs: List[Tuple[str,str,str]] = field(default_factory=list)  # name, raw, decoded
    children: List[Any] = field(default_factory=list)
    parent: Optional[Any] = None
    order: int = 0
    original_end: Optional[str] = None

_order_counter = 1

def next_order():
    global _order_counter
    v = _order_counter; _order_counter += 1; return v

def decode_entities(s: str) -> str:
    return htmlmod.unescape(s)

def escape_attr(v: str) -> str:
    return v.replace('&','&amp;').replace('"','&quot;')

def parse_attrs(s: str, lower=False):
    attrs=[]
    # remove trailing slash if present outside quotes (caller usually did)
    i=0; n=len(s)
    while i<n:
        while i<n and s[i].isspace(): i+=1
        if i>=n: break
        m=re.match(r'[^\s=/>]+', s[i:])
        if not m: break
        name=m.group(0); i += len(name)
        if lower: name=name.lower()
        while i<n and s[i].isspace(): i+=1
        val=''
        if i<n and s[i]=='=':
            i+=1
            while i<n and s[i].isspace(): i+=1
            if i<n and s[i] in ('"',"'"):
                q=s[i]; i+=1; start=i
                while i<n and s[i]!=q: i+=1
                val=s[start:i]
                if i<n: i+=1
            else:
                start=i
                while i<n and not s[i].isspace() and s[i] not in '/>': i+=1
                val=s[start:i]
        attrs.append((name, val, decode_entities(val)))
    return attrs

def split_tag_inside(inside: str):
    inside=inside.strip()
    if not inside: return '', ''
    parts=inside.split(None,1)
    if len(parts)==1: return parts[0], ''
    return parts[0], parts[1]

def tokenize(data: str, is_html=False):
    toks=[]; i=0; n=len(data)
    raw_tags = ('script','style')
    while i<n:
        if data.startswith('<!--', i):
            j=data.find('-->', i+4)
            if j<0: j=n-3
            toks.append(('comment', data[i+4:j])); i=min(j+3,n); continue
        if data.startswith('<![CDATA[', i):
            j=data.find(']]>', i+9)
            if j<0: j=n-3
            toks.append(('cdata', data[i+9:j])); i=min(j+3,n); continue
        if data.startswith('<?', i):
            j=data.find('?>', i+2)
            if j<0: j=n-2
            toks.append(('decl', data[i+2:j].strip())); i=min(j+2,n); continue
        if data.startswith('</', i):
            j=data.find('>', i+2)
            if j<0:
                toks.append(('text', data[i:])); break
            name=data[i+2:j].strip().split(None,1)[0] if data[i+2:j].strip() else ''
            if is_html: name=name.lower()
            toks.append(('end', name)); i=j+1; continue
        if data.startswith('<!', i):
            j=data.find('>', i+2)
            if j<0: j=n-1
            content=data[i+2:j].strip()
            if content.upper().startswith('DOCTYPE'):
                content='doctype' + content[7:]
            toks.append(('doctype', content)); i=min(j+1,n); continue
        if data[i]=='<':
            j=data.find('>', i+1)
            if j<0:
                toks.append(('badlt', data[i:])); break
            inside=data[i+1:j]
            selfclose=False
            # determine trailing slash outside simple cases
            stripped=inside.rstrip()
            if stripped.endswith('/'):
                selfclose=True; inside=stripped[:-1]
            name, rest=split_tag_inside(inside)
            if is_html: name=name.lower()
            attrs=parse_attrs(rest, lower=is_html)
            if is_html and name in VOID_HTML: selfclose=True
            toks.append(('start', name, attrs, selfclose))
            i=j+1
            if is_html and name in raw_tags and not selfclose:
                # Raw text until corresponding closing tag, if any.
                pat=re.compile(r'</\s*'+re.escape(name)+r'\s*>', re.I)
                m=pat.search(data, i)
                if m:
                    if m.start()>i: toks.append(('text_raw', data[i:m.start()]))
                    toks.append(('end', name))
                    i=m.end()
            continue
        j=data.find('<', i)
        if j<0: j=n
        toks.append(('text', data[i:j])); i=j
    return toks

def build_dom(data: str, is_html=False):
    global _order_counter
    _order_counter=1
    doc=Node('#document', order=0)
    stack=[doc]
    toks=tokenize(data, is_html)
    for t in toks:
        typ=t[0]
        if typ=='start':
            _, name, attrs, selfclose=t
            if not name: continue
            node=Node(name, attrs, [], stack[-1], next_order())
            stack[-1].children.append(node)
            if not selfclose:
                stack.append(node)
        elif typ=='end':
            name=t[1]
            if len(stack)>1:
                stack[-1].original_end=name
                # Prefer popping matching tag if it is on top; otherwise mimic a tolerant tokenizer
                if stack[-1].tag==name:
                    stack.pop()
                else:
                    # pop one; this preserves many malformed-input quirks without building a validator
                    stack.pop()
        elif typ=='text' or typ=='text_raw':
            txt=t[1]
            if typ=='text': txt=decode_entities(txt)
            if txt!='': stack[-1].children.append(Text(txt))
        elif typ=='cdata':
            stack[-1].children.append(Text(t[1], cdata=True))
        elif typ=='comment':
            stack[-1].children.append(Comment(t[1]))
        elif typ in ('decl','doctype'):
            stack[-1].children.append(Special(typ, t[1]))
        elif typ=='badlt':
            stack[-1].children.append(Text(t[1]))
    return doc

def attr_string(attrs):
    if not attrs: return ''
    return ''.join(' '+n+'="'+v+'"' for n,v,_ in attrs)

def format_text_xml(s: str, cdata=False):
    s=s.rstrip()
    if cdata:
        return '<![CDATA['+s+']]>'
    if any(ch in s for ch in ['<','>','&','"',"'"]):
        return '<![CDATA['+s+']]>'
    return s

def format_text_html(s: str):
    return s.rstrip()

def element_children(node):
    return [c for c in node.children if isinstance(c, Node)]

def visible_texts(children):
    return [c for c in children if isinstance(c, Text) and c.text.strip()!='']

def one_line_node(node: Node, is_html=False):
    attrs=attr_string(node.attrs)
    if is_html and node.tag not in VOID_HTML:
        return f'<{node.tag}{attrs}></{node.tag}>'
    return f'<{node.tag}{attrs}/>'

def format_node(node: Node, unit='  ', level=0, is_html=False):
    ind=unit*level
    attrs=attr_string(node.attrs)
    elems=element_children(node)
    # significant non-whitespace text nodes
    sig_text=[c for c in node.children if isinstance(c, Text) and c.text.strip()!='']
    comments=[c for c in node.children if isinstance(c, Comment)]
    specials=[c for c in node.children if isinstance(c, Special)]
    if not elems and not sig_text and not comments and not specials:
        if is_html and node.tag not in VOID_HTML:
            return [ind+f'<{node.tag}{attrs}></{node.tag}>']
        return [ind+f'<{node.tag}{attrs}/>']
    if not elems and not comments and not specials:
        txt=''.join(c.text for c in node.children if isinstance(c,Text))
        cdata=any(c.cdata for c in node.children if isinstance(c,Text))
        ft = format_text_html(txt) if is_html else format_text_xml(txt, cdata)
        return [ind+f'<{node.tag}{attrs}>'+ft+f'</{node.tag}>']
    lines=[]
    # opening, possibly with first text attached
    children=list(node.children)
    first_text=''; first_cdata=False
    idx=0
    if children and isinstance(children[0], Text) and children[0].text.strip()!='':
        first_text=children[0].text; first_cdata=children[0].cdata; idx=1
    if first_text:
        ft=format_text_html(first_text) if is_html else format_text_xml(first_text, first_cdata)
        lines.append(ind+f'<{node.tag}{attrs}>'+ft)
    else:
        lines.append(ind+f'<{node.tag}{attrs}>')
    last_tail=False
    for c in children[idx:]:
        if isinstance(c, Node):
            lines.extend(format_node(c, unit, level+1, is_html))
            last_tail=False
        elif isinstance(c, Comment):
            lines.append(unit*(level+1)+'<!--'+c.text+'-->')
            last_tail=False
        elif isinstance(c, Special):
            if c.kind=='doctype': lines.append(unit*(level+1)+'<!'+c.text+'>')
            else: lines.append(unit*(level+1)+'<?'+c.text+'?>')
            last_tail=False
        elif isinstance(c, Text):
            if c.text.strip()!='':
                ft=format_text_html(c.text) if is_html else format_text_xml(c.text, c.cdata)
                if lines:
                    lines[-1] += ft
                else:
                    lines.append(ind+ft)
                last_tail=True
    close=f'</{node.tag}>'
    if last_tail:
        lines[-1] += close
    else:
        lines.append(ind+close)
    return lines

def format_document(data: str, is_html=False, indent=2, tab=False):
    if data == '':
        raise ValueError('unknown content type: 3')
    if not is_html and data == '<':
        raise ValueError('XML syntax error on line 1: unexpected EOF')
    doc=build_dom(data, is_html)
    unit='\t' if tab else ' '*indent
    lines=[]
    for c in doc.children:
        if isinstance(c, Node):
            lines.extend(format_node(c, unit, 0, is_html))
        elif isinstance(c, Text):
            lines.append((format_text_html(c.text) if is_html else format_text_xml(c.text, c.cdata)))
        elif isinstance(c, Comment):
            lines.append('<!--'+c.text+'-->')
        elif isinstance(c, Special):
            if c.kind=='doctype': lines.append('<!'+c.text+'>')
            else: lines.append('<?'+c.text+'?>')
    return '\n'.join(lines)+'\n'

# Text helpers

def all_text(node: Node, sep=''):
    parts=[]
    def rec(x):
        if isinstance(x, Text):
            s=x.text.strip()
            if s!='': parts.append(s)
        elif isinstance(x, Node):
            for ch in x.children: rec(ch)
    rec(node)
    return sep.join(parts)

def direct_texts(node: Node):
    return [c.text.strip() for c in node.children if isinstance(c,Text) and c.text.strip()!='']

def direct_text_join(node: Node, sep=''):
    return sep.join(direct_texts(node))

def descendants_including_roots(nodes):
    out=[]
    def rec(n):
        if isinstance(n,Node) and n.tag!='#document':
            out.append(n)
        if isinstance(n,Node):
            for ch in n.children:
                if isinstance(ch,Node): rec(ch)
    for n in nodes: rec(n)
    return out

def child_elements(n):
    return [c for c in n.children if isinstance(c,Node)]

def qname_local(name):
    if name.startswith('xmlns:'):
        return name.split(':',1)[1]
    if ':' in name:
        return name.split(':',1)[1]
    return name

def parse_step(step):
    pred=None
    m=re.match(r'^(.*)\[(.+)\]$', step)
    if m:
        step=m.group(1); pred=m.group(2)
    return step, pred

def match_step(n: Node, name: str):
    return name=='*' or n.tag==name

def apply_pred(candidates, pred):
    if pred is None: return candidates
    pred=pred.strip()
    if pred.isdigit():
        idx=int(pred)
        return [candidates[idx-1]] if 1 <= idx <= len(candidates) else []
    m=re.match(r'^@([^=\]]+)$', pred)
    if m:
        an=m.group(1)
        return [c for c in candidates if any(a[0]==an for a in c.attrs)]
    m=re.match(r'^@([^=\]]+)\s*=\s*["\'](.*)["\']$', pred)
    if m:
        an, val=m.group(1), m.group(2)
        return [c for c in candidates if any(a[0]==an and a[2]==val for a in c.attrs)]
    return []

@dataclass
class AttrResult:
    name: str
    value: str

@dataclass
class TextResult:
    value: str

def select_xpath(doc: Node, expr: str):
    if '[' in expr and not re.search(r'\[[^\]]+\]', expr):
        raise SyntaxError()
    if expr == '/':
        return [doc]
    # normalize // into marker
    if expr.startswith('//@'):
        an=expr[3:]
        res=[]
        for n in descendants_including_roots([doc]):
            for a in n.attrs:
                if a[0]==an: res.append(AttrResult(an,a[2]))
        return res
    mode='abs'
    rest=expr
    cur=[doc]
    if expr.startswith('//'):
        mode='desc'; rest=expr[2:]
    elif expr.startswith('/'):
        rest=expr[1:]
    parts=[p for p in rest.split('/') if p!='']
    if not parts: return cur
    for pi, part in enumerate(parts):
        if part=='text()':
            return [TextResult(t) for n in cur if isinstance(n,Node) for t in direct_texts(n)]
        if part.startswith('@'):
            an=part[1:]
            return [AttrResult(an,a[2]) for n in cur if isinstance(n,Node) for a in n.attrs if a[0]==an]
        if part=='..':
            cur=[] if not cur else list(dict.fromkeys([n.parent for n in cur if isinstance(n,Node) and n.parent is not None and n.parent.tag!='#document']))
            continue
        name,pred=parse_step(part)
        nxt=[]
        if pi==0 and mode=='desc':
            # XPath //foo means find child foo of every node in document order; this makes //foo[1] sibling-relative.
            parents=[doc]+descendants_including_roots([doc])
            for p in parents:
                cand=[c for c in child_elements(p) if match_step(c,name)]
                nxt.extend(apply_pred(cand,pred))
        else:
            for n in cur:
                if not isinstance(n,Node): continue
                cand=[c for c in child_elements(n) if match_step(c,name)]
                nxt.extend(apply_pred(cand,pred))
        cur=nxt
    return cur

# CSS
@dataclass
class SimpleSel:
    tag: str='*'
    id: Optional[str]=None
    classes: List[str]=field(default_factory=list)
    attrs: List[Tuple[str,Optional[str]]]=field(default_factory=list)
    pseudo: Optional[Tuple[str,Optional[int]]]=None

def parse_simple_selector(s: str):
    sel=SimpleSel()
    i=0; n=len(s)
    m=re.match(r'^[A-Za-z0-9_:-]+|^\*', s)
    if m:
        sel.tag=m.group(0).lower(); i=len(m.group(0))
    while i<n:
        if s[i]=='.':
            i+=1; m=re.match(r'[A-Za-z0-9_-]+', s[i:])
            if not m: break
            sel.classes.append(m.group(0)); i+=len(m.group(0))
        elif s[i]=='#':
            i+=1; m=re.match(r'[A-Za-z0-9_-]+', s[i:])
            if not m: break
            sel.id=m.group(0); i+=len(m.group(0))
        elif s[i]=='[':
            j=s.find(']', i+1)
            if j<0: break
            cont=s[i+1:j]
            if '=' in cont:
                a,v=cont.split('=',1); v=v.strip().strip('"\'')
                sel.attrs.append((a.strip().lower(), decode_entities(v)))
            else:
                sel.attrs.append((cont.strip().lower(), None))
            i=j+1
        elif s[i]==':':
            if s.startswith(':first-child', i): sel.pseudo=('first',None); i+=12
            elif s.startswith(':last-child', i): sel.pseudo=('last',None); i+=11
            else:
                m=re.match(r':nth-child\((\d+)\)', s[i:])
                if m: sel.pseudo=('nth', int(m.group(1))); i+=len(m.group(0))
                else: break
        else:
            i+=1
    return sel

def tokenize_selector(sel: str):
    tokens=[]; buf=''; comb='desc'; bracket=0; paren=0; quote=None; pending_space=False
    def flush():
        nonlocal buf, comb, pending_space
        b=buf.strip()
        if b:
            tokens.append((comb, parse_simple_selector(b)))
            buf=''; comb='desc'; pending_space=False
    for ch in sel.strip():
        if quote:
            buf+=ch
            if ch==quote: quote=None
            continue
        if ch in ('"',"'"):
            quote=ch; buf+=ch; continue
        if ch=='[': bracket+=1; buf+=ch; continue
        if ch==']': bracket-=1; buf+=ch; continue
        if ch=='(': paren+=1; buf+=ch; continue
        if ch==')': paren-=1; buf+=ch; continue
        if bracket==0 and paren==0 and ch=='>':
            flush(); comb='child'; pending_space=False; continue
        if bracket==0 and paren==0 and ch.isspace():
            flush();
            if tokens: comb='desc'
            continue
        buf+=ch
    flush()
    if tokens:
        # first selector is relative descendant from document root
        tokens[0]=('root', tokens[0][1])
    return tokens

def attr_dict(n: Node): return {a[0]:a[2] for a in n.attrs}

def css_match(n: Node, sel: SimpleSel):
    if sel.tag!='*' and n.tag!=sel.tag: return False
    ad=attr_dict(n)
    if sel.id is not None and ad.get('id')!=sel.id: return False
    classes=ad.get('class','').split()
    for c in sel.classes:
        if c not in classes: return False
    for a,v in sel.attrs:
        if a not in ad: return False
        if v is not None and ad.get(a)!=v: return False
    if sel.pseudo:
        if not n.parent: return False
        sib=child_elements(n.parent)
        idx=sib.index(n)+1 if n in sib else -1
        kind,num=sel.pseudo
        if kind=='first' and idx!=1: return False
        if kind=='last' and idx!=len(sib): return False
        if kind=='nth' and idx!=num: return False
    return True

def normalize_html_doc(doc: Node):
    # If no html node, wrap content in html/head/body; if html exists ensure head and body exist for selector behavior.
    elems=child_elements(doc)
    htmln=None
    for e in elems:
        if e.tag=='html': htmln=e; break
    if htmln is None:
        htmln=Node('html', [], [], doc, next_order())
        head=Node('head', [], [], htmln, next_order())
        body=Node('body', [], [], htmln, next_order())
        old=doc.children[:]
        doc.children=[htmln]
        htmln.children=[head, body]
        for c in old:
            c.parent=body if isinstance(c,Node) else getattr(c,'parent',None)
            body.children.append(c)
        return doc
    heads=[c for c in child_elements(htmln) if c.tag=='head']
    bodies=[c for c in child_elements(htmln) if c.tag=='body']
    if not heads:
        head=Node('head', [], [], htmln, next_order())
        htmln.children.insert(0, head)
    if not bodies:
        body=Node('body', [], [], htmln, next_order())
        move=[c for c in htmln.children if isinstance(c,Node) and c.tag!='head']
        htmln.children=[c for c in htmln.children if not (isinstance(c,Node) and c.tag!='head')]
        htmln.children.append(body)
        for c in move:
            c.parent=body; body.children.append(c)
    return doc

def select_css(doc: Node, selector: str):
    groups=[g.strip() for g in selector.split(',') if g.strip()]
    allres=[]
    for g in groups:
        toks=tokenize_selector(g)
        if not toks: continue
        cur=[doc]
        for comb, simple in toks:
            nxt=[]
            if comb in ('root','desc'):
                seen=[]
                for n in cur:
                    for d in descendants_including_roots([n]):
                        if css_match(d, simple): seen.append(d)
                nxt=seen
            elif comb=='child':
                for n in cur:
                    for c in child_elements(n):
                        if css_match(c, simple): nxt.append(c)
            cur=nxt
        allres.extend(cur)
    # unique in document order
    uniq={n.order:n for n in allres}
    return [uniq[k] for k in sorted(uniq)]

# JSON conversion/writer
class EmptyObj: pass
EMPTY=EmptyObj()

def text_for_depth(node: Node):
    vals=[]
    def rec(n):
        if isinstance(n,Text):
            s=n.text.strip()
            if s!='': vals.append(s)
        elif isinstance(n,Node):
            elems=child_elements(n)
            if not elems and not any(isinstance(c,Text) and c.text.strip()!='' for c in n.children):
                vals.append('')
            else:
                for c in n.children: rec(c)
    rec(node)
    # trim leading/trailing empty strings like strings.TrimSpace on joined value
    joined='\n'.join(vals)
    return joined.strip('\n')

def node_to_json_value(node: Node, depth=-1, level=0):
    if depth>=0 and level>=depth:
        return text_for_depth(node)
    attrs=node.attrs
    elems=child_elements(node)
    dtexts=direct_texts(node)
    if not attrs and not elems:
        if dtexts: return '\n'.join(dtexts)
        return EMPTY
    obj={}
    if dtexts:
        obj['#text']='\n'.join(dtexts)
    for name,raw,val in attrs:
        obj['@'+qname_local(name)]=val
    groups={}
    for ch in elems:
        key=qname_local(ch.tag)
        groups.setdefault(key,[]).append(node_to_json_value(ch, depth, level+1))
    for k,vals in groups.items():
        obj[k]=vals if len(vals)>1 else vals[0]
    return obj

def json_escape(s):
    return json.dumps(s, ensure_ascii=False)

def write_json_val(v, compact=False, level=0):
    ind='  '*level
    if isinstance(v, EmptyObj):
        return '{}' if compact else '{\n\n' + ind + '}'
    if isinstance(v, str): return json_escape(v)
    if isinstance(v, (int,float)) or v is None or isinstance(v,bool): return json.dumps(v)
    if isinstance(v, list):
        if not v: return '[]'
        if compact:
            return '['+','.join(write_json_val(x, True, level) for x in v)+']'
        inner=[]
        for i,x in enumerate(v):
            s='  '*(level+1)+write_json_val(x, False, level+1)
            if i<len(v)-1: s+=','
            inner.append(s)
        return '[\n'+'\n'.join(inner)+'\n'+ind+']'
    if isinstance(v, dict):
        keys=sorted(v.keys())
        if not keys: return '{}' if compact else '{\n\n'+ind+'}'
        if compact:
            return '{'+','.join(json_escape(k)+': '+write_json_val(v[k], True, level) for k in keys)+'}'
        inner=[]
        for i,k in enumerate(keys):
            s='  '*(level+1)+json_escape(k)+': '+write_json_val(v[k], False, level+1)
            if i<len(keys)-1: s+=','
            inner.append(s)
        return '{\n'+'\n'.join(inner)+'\n'+ind+'}'
    return json_escape(str(v))

def xml_to_json(data: str, depth=-1, compact=False):
    # Try strict XML parse for bad mismatches? Use minidom for detecting common malformed inputs, but keep our DOM for conversion.
    try:
        import xml.dom.minidom as minidom
        minidom.parseString(data.encode())
    except Exception as e:
        msg=str(e)
        # expat messages are close enough; match common observed form for mismatched tags
        if 'mismatched tag' in msg:
            raise ValueError('error while parsing XML: XML syntax error on line 1: element <a> closed by </root>')
        raise ValueError('error while parsing XML: '+msg)
    doc=build_dom(data, False)
    roots=child_elements(doc)
    obj={}
    for r in roots:
        obj[qname_local(r.tag)]=node_to_json_value(r, depth, 0)
    return write_json_val(obj, compact, 0)+'\n'

# colorizer
Y='\033[33m'; G='\033[32m'; R='\033[0m'

def colorize_tag(tag: str):
    if tag.startswith('</'):
        return Y+tag+R
    if tag.startswith('<!doctype'):
        return Y+'<!doctype '+R+tag[len('<!doctype '):-1]+Y+'>'+R if tag.startswith('<!doctype ') else Y+tag+R
    if tag.startswith('<?'):
        return Y+tag+R
    if tag.startswith('<!--'):
        return Y+tag+R
    if tag.startswith('<![CDATA['):
        return tag
    m=re.match(r'<([^\s/>]+)(.*?)(/?)>$', tag, re.S)
    if not m: return Y+tag+R
    name, rest, slash=m.group(1), m.group(2), m.group(3)
    out=Y+'<'+name+R
    # color only ="..." parts green, keep attr names normal
    pos=0
    for mm in re.finditer(r'="[^"]*"', rest):
        out += rest[pos:mm.start()] + G + mm.group(0) + R
        pos=mm.end()
    out += rest[pos:]
    out += Y+('/>' if slash else '>')+R
    return out

def colorize(s: str):
    # Avoid coloring pseudo-tags inside CDATA poorly by a simple tag regex matching known tag-like spans.
    def repl(m): return colorize_tag(m.group(0))
    return re.sub(r'</?[^<>\s!/?][^<>]*?/?>|<!doctype [^<>]*>|<!--.*?-->|<\?[^<>]*?\?>', repl, s)

# CLI
class Opt:
    def __init__(self):
        self.attr=None; self.color=False; self.no_color=False; self.compact=False; self.depth=-1; self.extract=None; self.help=False; self.html=False; self.in_place=False; self.indent=2; self.json=False; self.node=False; self.query=None; self.tab=False; self.version=False; self.xpath=None; self.files=[]

def parse_int_flag(val, flagdesc):
    try: return int(val)
    except Exception:
        raise ValueError(f'invalid argument "{val}" for "{flagdesc}" flag: strconv.ParseInt: parsing "{val}": invalid syntax')

def parse_args(argv):
    o=Opt(); i=0
    long_with_arg={'--attr':'attr','--extract':'extract','--indent':'indent','--xpath':'xpath','--query':'query','--depth':'depth'}
    long_bool={'--color':'color','--no-color':'no_color','--compact':'compact','--help':'help','--html':'html','--in-place':'in_place','--json':'json','--node':'node','--tab':'tab','--version':'version'}
    short_arg={'a':'attr','e':'extract','x':'xpath','q':'query','d':'depth'}
    short_bool={'c':'color','h':'help','m':'html','i':'in_place','j':'json','n':'node','v':'version'}
    while i<len(argv):
        arg=argv[i]
        if arg=='--': o.files.extend(argv[i+1:]); break
        if arg.startswith('--'):
            name=arg; val=None
            if '=' in arg:
                name,val=arg.split('=',1)
            if name in long_bool:
                setattr(o,long_bool[name],True)
            elif name in long_with_arg:
                if val is None:
                    if i+1>=len(argv): raise ValueError(f'flag needs an argument: {name}')
                    i+=1; val=argv[i]
                attr=long_with_arg[name]
                if attr=='indent': val=parse_int_flag(val, '--indent')
                if attr=='depth': val=parse_int_flag(val, '-d, --depth')
                setattr(o, attr, val)
            else:
                raise ValueError('unknown flag: '+arg)
        elif arg.startswith('-') and arg!='-':
            s=arg[1:]; j=0
            while j<len(s):
                ch=s[j]
                if ch in short_bool:
                    setattr(o,short_bool[ch],True); j+=1
                    continue
                if ch in short_arg:
                    if j+1<len(s):
                        val=s[j+1:]; j=len(s)
                    else:
                        if i+1>=len(argv): raise ValueError(f"flag needs an argument: '{ch}' in -{ch}")
                        i+=1; val=argv[i]; j=len(s)
                    attr=short_arg[ch]
                    if attr=='depth': val=parse_int_flag(val, '-d, --depth')
                    setattr(o,attr,val)
                    break
                raise ValueError('unknown shorthand flag: '+ch)
        else:
            o.files.append(arg)
        i+=1
    return o

def read_inputs(files):
    if files:
        out=''
        for f in files:
            try:
                with open(f,'r',encoding='utf-8') as fh: out += fh.read()
            except OSError as e:
                raise FileNotFoundError(f'open {f}: no such file or directory')
        return out
    return sys.stdin.read()

def produce(data, opt: Opt):
    if opt.attr and not opt.query:
        raise RuntimeError('ERR_STDERR:query option (-q) is missed for attribute selection')
    if opt.json:
        return xml_to_json(data, opt.depth, opt.compact)
    if opt.query:
        doc=normalize_html_doc(build_dom(data, True))
        nodes=select_css(doc, opt.query)
        lines=[]
        if opt.attr:
            for n in nodes:
                ad=attr_dict(n)
                lines.append(ad.get(opt.attr,''))
            return '\n'.join(lines)+('\n' if lines else '')
        if opt.node:
            unit='\t' if opt.tab else ' '*opt.indent
            out=[]
            for n in nodes:
                out.extend(format_node(n, unit, 0, True))
            return '\n'.join(out)+('\n' if out else '')
        for n in nodes:
            lines.append(all_text(n,''))
        return '\n'.join(lines)+('\n' if lines else '')
    xp=opt.xpath or opt.extract
    if xp:
        try:
            doc=build_dom(data, False)
            res=select_xpath(doc, xp)
        except SyntaxError:
            raise RuntimeError('ERR_STDOUT:unable to parse the XPath query')
        if opt.extract:
            res=res[:1]
        if opt.node:
            out=[]; unit='\t' if opt.tab else ' '*opt.indent
            for r in res:
                if isinstance(r,Node): out.extend(format_node(r, unit, 0, False))
                elif isinstance(r,AttrResult): out.extend(format_node(Node(r.name, [], [Text(r.value)]), unit,0,False))
                elif isinstance(r,TextResult): out.append(r.value)
            return '\n'.join(out)+('\n' if out else '')
        lines=[]
        for r in res:
            if isinstance(r,Node): lines.append(all_text(r,''))
            elif isinstance(r,AttrResult): lines.append(r.value)
            elif isinstance(r,TextResult): lines.append(r.value)
            else: lines.append('')
        return '\n'.join(lines)+('\n' if lines else '')
    out=format_document(data, opt.html, opt.indent, opt.tab)
    if opt.color and not opt.no_color:
        out=colorize(out)
    return out

def main(argv):
    try:
        opt=parse_args(argv)
    except ValueError as e:
        print('Error: '+str(e), file=sys.stderr); return 1
    if opt.help:
        sys.stdout.write(HELP); return 0
    if opt.version:
        print('xq version 1.4.0'); return 0
    if not opt.files and sys.stdin.isatty():
        sys.stdout.write(HELP); return 0
    if opt.in_place and len(opt.files)!=1:
        print('Error: in-place formatting requires a file path (and only one file path)', file=sys.stderr); return 1
    try:
        data=read_inputs(opt.files)
    except FileNotFoundError as e:
        print('Error: '+str(e), file=sys.stderr); return 1
    try:
        out=produce(data,opt)
    except ValueError as e:
        print('Error: '+str(e)); return 1
    except RuntimeError as e:
        msg=str(e)
        if msg.startswith('ERR_STDERR:'):
            print('Error: '+msg[len('ERR_STDERR:'):], file=sys.stderr); return 1
        if msg.startswith('ERR_STDOUT:'):
            print('Error: '+msg[len('ERR_STDOUT:'):]); return 1
        print('Error: '+msg, file=sys.stderr); return 1
    if opt.in_place:
        with open(opt.files[0],'w',encoding='utf-8') as fh: fh.write(out)
    else:
        sys.stdout.write(out)
    return 0

if __name__=='__main__':
    sys.exit(main(sys.argv[1:]))
